const crypto = require('crypto');
const length = parseInt(argumentName?.trim()) || 16;
if (length < 8 || length > 128) return sendTrackedMessage(sock, remoteJid, 'Password length must be 8-128');
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
let password = '';
const bytes = crypto.randomBytes(length);
for (let i = 0; i < length; i++) {
  password += chars[bytes[i] % chars.length];
}
await sendTrackedMessage(sock, remoteJid, `🔐 Your ${length}-character password:\n${password}\n\n⚠️ Copy it now — it won't be saved!`);
